463→    messagesEl.appendChild(msg);
464→    messagesEl.scrollTop = messagesEl.scrollHeight;
465→    return bubble;
466→  }
467→
468→  function copyMessage(text, btn) {
469→    navigator.clipboard.writeText(text).then(() => {
470→      const originalText = btn.textContent;
471→      btn.textContent = 'Copied!';
472→      btn.classList.add('copied');
473→      setTimeout(() => {
474→        btn.textContent = originalText;
475→        btn.classList.remove('copied');
476→      }, 2000);
477→    }).catch(err => {
478→      console.error('Failed to copy:', err);
479→    });
480→  }
481→
482→  function downloadConversation() {
483→    if (conversationHistory.length === 0) {
484→      alert('No conversation to download yet!');
485→      return;
486→    }
487→
488→    // Build markdown format
489→    let markdown = '# Safecast Radiation Assistant Conversation\n\n';
490→    markdown += `Date: ${new Date().toLocaleString()}\n\n`;
491→    markdown += '---\n\n';
492→
493→    conversationHistory.forEach(msg => {
494→      const role = msg.role === 'user' ? 'You' : 'Assistant';
495→      markdown += `## ${role}\n\n`;
496→      markdown += msg.content + '\n\n';
497→      markdown += '---\n\n';
498→    });
499→
500→    // Create download link
501→    const blob = new Blob([markdown], { type: 'text/markdown' });
502→    const url = URL.createObjectURL(blob);
503→    const a = document.createElement('a');
504→    a.href = url;
505→    a.download = `safecast-conversation-${new Date().toISOString().slice(0,10)}.md`;
506→    document.body.appendChild(a);
507→    a.click();
508→    document.body.removeChild(a);
509→    URL.revokeObjectURL(url);
510→  }
511→
512→  function clearConversation() {
513→    // Clear conversation history
514→    conversationHistory = [];
515→
516→    // Clear all messages
517→    while (messagesEl.firstChild) {
518→      messagesEl.removeChild(messagesEl.firstChild);
519→    }
520→
521→    // Show intro again
522→    messagesEl.appendChild(introEl);
523→    introEl.style.display = 'block';
524→
525→    // Focus on input
526→    msgEl.focus();
527→  }
528→
529→  function sendMessage(text) {
530→    busy = true;
531→    sendBtn.disabled = true;
532→
533→    addMessage('user', text);
534→    const botBubble = addMessage('bot', '…thinking…', 'thinking');
535→
536→    let accumulated = '';
537→
538→    function finish(success = true) {
539→      botBubble.classList.remove('thinking');
540→      busy = false;
541→      sendBtn.disabled = false;
542→      msgEl.focus();
543→
544→      // Add AI disclaimer to successful bot messages
545→      if (success && accumulated) {
546→        // Re-render with disclaimer
547→        const disclaimerText = '\n\n---\n\n_Note: AI-generated response using data from the Safecast radiation monitoring network. For critical safety decisions, please consult official sources._';
548→        botBubble.innerHTML = markdownToHTML(accumulated + disclaimerText);
549→
550→        // Re-add copy button (since we replaced innerHTML)
551→        const copyBtn = document.createElement('button');
552→        copyBtn.className = 'copy-btn';
553→        copyBtn.textContent = 'Copy';
554→        copyBtn.onclick = () => copyMessage(accumulated, copyBtn); // Copy without disclaimer
555→        botBubble.appendChild(copyBtn);
556→
557→        conversationHistory.push(
558→          { role: 'user', content: text },
559→          { role: 'assistant', content: accumulated }
560→        );
561→
562→        // Keep only last 10 messages (5 exchanges) to prevent rate limits
563→        const MAX_HISTORY = 10;
564→        if (conversationHistory.length > MAX_HISTORY) {
565→          conversationHistory = conversationHistory.slice(-MAX_HISTORY);
566→        }
567→      }
568→    }
569→
570→    fetch('/chat', {
571→      method: 'POST',
572→      headers: { 'Content-Type': 'application/json' },
573→      body: JSON.stringify({
574→        message: text,
575→        history: conversationHistory
576→      }),
577→    }).then(response => {
578→      const reader  = response.body.getReader();
579→      const decoder = new TextDecoder();
580→      let   buffer  = '';
581→
582→      function pump() {
583→        return reader.read().then(({ done, value }) => {
584→          if (done) { finish(); return; }
585→
586→          buffer += decoder.decode(value, { stream: true });
587→          const lines = buffer.split('\n');
588→          buffer = lines.pop(); // keep incomplete last line
589→
590→          for (const line of lines) {
591→            if (!line.trim()) continue;
592→            try {
593→              const ev = JSON.parse(line);
594→              if (ev.type === 'text') {
595→                if (botBubble.classList.contains('thinking')) {
596→                  botBubble.classList.remove('thinking');
597→                  accumulated = '';
598→                }
599→                accumulated += ev.text;
600→                botBubble.innerHTML = markdownToHTML(accumulated);
601→                messagesEl.scrollTop = messagesEl.scrollHeight;
602→              } else if (ev.type === 'done') {
603→                finish();
604→              } else if (ev.type === 'error') {
605→                botBubble.classList.remove('thinking');
606→                botBubble.classList.add('error');
607→                botBubble.textContent = 'Error: ' + ev.error;
608→                finish(false);
609→              }
610→            } catch { /* malformed line, skip */ }
611→          }
612→          return pump();
613→        });
614→      }
615→      return pump();
616→    }).catch(err => {
617→      botBubble.classList.remove('thinking');
618→      botBubble.classList.add('error');
619→      botBubble.textContent = 'Connection error: ' + err.message;
620→      finish(false);
621→    });
622→  }
623→
624→  msgEl.focus();
625→</script>
